  started_at    TEXT NOT NULL,
  finished_at   TEXT,
  status        TEXT NOT NULL,
  http_status   INTEGER,
  item_count    INTEGER,
  duration_ms   INTEGER,
  error         TEXT
, response_ms INTEGER, category TEXT);

CREATE TABLE inventory_latest (
  sku              TEXT NOT NULL,
  store_key        TEXT NOT NULL,
  quantity         INTEGER,
  store_total_qty  INTEGER,
  on_order_qty     INTEGER,
