  seen             TEXT NOT NULL DEFAULT '',  -- comma-separated SKUs seen (for vanish detection)
  degraded         TEXT,                 -- reason vanish inference is not allowed (e.g. total drift)
  vanished_applied INTEGER,
  vanish_skipped   TEXT,
  error            TEXT,
  started_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  completed_at     TEXT
, retry_json TEXT, retried INTEGER NOT NULL DEFAULT 0, recovered INTEGER NOT NULL DEFAULT 0, retry_requests INTEGER NOT NULL DEFAULT 0, transient_errors INTEGER NOT NULL DEFAULT 0, rest_cycles INTEGER NOT NULL DEFAULT 0, page_failures_json TEXT, catchup_status TEXT, catchup_note TEXT, catchup_started_at TEXT, catchup_finished_at TEXT, catchup_base_requests INTEGER, catchup_end_requests INTEGER, catchup_base_pages INTEGER, catchup_base_retry INTEGER, catchup_base_transients INTEGER, catchup_unfinished INTEGER, catchup_perstore TEXT, catchup_perstore_note TEXT);

